from __future__ import annotations

import argparse
from dataclasses import dataclass
from pathlib import Path
import re
from typing import Iterable

import numpy as np
from sentence_transformers import SentenceTransformer


DEFAULT_MODEL = "sentence-transformers/all-MiniLM-L6-v2"
RECAPS_FOLDER = Path(__file__).parent / "recaps"


@dataclass
class Chunk:
    document_id: int
    chunk_id: int
    text: str


@dataclass
class Document:
    document_id: int
    path: Path
    title: str
    text: str


class SemanticRecapSearch:
    def __init__(
        self,
        recap_folder: str,
        model_name: str = DEFAULT_MODEL,
        chunk_size: int = 180,
        chunk_overlap: int = 40,
    ):
        if chunk_overlap >= chunk_size:
            raise ValueError(
                "chunk_overlap must be smaller than chunk_size"
            )

        self.recap_folder = Path(recap_folder)
        self.chunk_size = chunk_size
        self.chunk_overlap = chunk_overlap

        self.documents = self._load_documents()

        if not self.documents:
            raise ValueError(
                f"No Markdown files found in {self.recap_folder}"
            )

        self.chunks = self._create_chunks()

        print(f"Loading embedding model: {model_name}")
        self.model = SentenceTransformer(model_name)

        self.chunk_embeddings = self._embed_documents()

    # ------------------------------------------------------------
    # Loading Markdown documents
    # ------------------------------------------------------------

    def _load_documents(self) -> list[Document]:
        documents = []

        markdown_files = sorted(
            self.recap_folder.rglob("*.md")
        )

        for document_id, path in enumerate(markdown_files):
            if not path.is_file():
                continue

            text = path.read_text(encoding="utf-8")
            title = self._extract_title(text, fallback=path.stem)

            documents.append(
                Document(
                    document_id=document_id,
                    path=path,
                    title=title,
                    text=text,
                )
            )

        return documents

    @staticmethod
    def _extract_title(text: str, fallback: str) -> str:
        for line in text.splitlines():
            if line.startswith("# "):
                return line[2:].strip()

        return fallback

    # ------------------------------------------------------------
    # Chunking
    # ------------------------------------------------------------

    def _create_chunks(self) -> list[Chunk]:
        chunks = []

        for document in self.documents:
            document_chunks = self._chunk_text(document.text)

            for chunk_id, chunk_text in enumerate(document_chunks):
                chunks.append(
                    Chunk(
                        document_id=document.document_id,
                        chunk_id=chunk_id,
                        text=chunk_text,
                    )
                )

        return chunks

    def _chunk_text(self, text: str) -> list[str]:
        """
        Split text into overlapping word-based chunks.

        This intentionally uses a simple tokenizer so that students
        can see the chunking process without requiring a Markdown
        parser.
        """
        words = re.findall(r"\S+", text)

        if not words:
            return []

        chunks = []
        start = 0

        while start < len(words):
            end = min(
                start + self.chunk_size,
                len(words),
            )

            chunk = " ".join(words[start:end])
            chunks.append(chunk)

            if end == len(words):
                break

            start = end - self.chunk_overlap

        return chunks

    # ------------------------------------------------------------
    # Embeddings
    # ------------------------------------------------------------

    def _embed_documents(self) -> np.ndarray:
        texts = [chunk.text for chunk in self.chunks]

        """
        encode_document is appropriate for corpus passages in
        asymmetric semantic search.

        The fallback makes the example work with older versions of
        sentence-transformers or models without specialized prompts.
        """
        if hasattr(self.model, "encode_document"):
            embeddings = self.model.encode_document(
                texts,
                normalize_embeddings=True,
                show_progress_bar=True,
            )
        else:
            embeddings = self.model.encode(
                texts,
                normalize_embeddings=True,
                show_progress_bar=True,
            )

        return np.asarray(embeddings, dtype=np.float32)

    def _embed_query(self, query: str) -> np.ndarray:
        if hasattr(self.model, "encode_query"):
            embedding = self.model.encode_query(
                query,
                normalize_embeddings=True,
            )
        else:
            embedding = self.model.encode(
                query,
                normalize_embeddings=True,
            )

        return np.asarray(embedding, dtype=np.float32)

    # ------------------------------------------------------------
    # Search
    # ------------------------------------------------------------

    def search(
        self,
        query: str,
        top_k: int = 5,
        min_score: float | None = None,
    ) -> list[dict]:
        """
        Return the best matching recap documents.

        Each document receives the score of its best matching chunk.
        """
        if not query.strip():
            return []

        query_embedding = self._embed_query(query)

        # Because both query and chunk embeddings are normalized,
        # the dot product is cosine similarity.
        chunk_scores = self.chunk_embeddings @ query_embedding

        document_results = {}

        for chunk_index, score in enumerate(chunk_scores):
            chunk = self.chunks[chunk_index]
            score = float(score)

            if min_score is not None and score < min_score:
                continue

            existing = document_results.get(chunk.document_id)

            candidate = {
                "document_id": chunk.document_id,
                "score": score,
                "chunk_id": chunk.chunk_id,
                "matching_chunk": chunk.text,
            }

            if existing is None or score > existing["score"]:
                document_results[chunk.document_id] = candidate

        ranked_results = sorted(
            document_results.values(),
            key=lambda result: result["score"],
            reverse=True,
        )

        results = []

        for result in ranked_results[:top_k]:
            document = self.documents[result["document_id"]]

            results.append(
                {
                    "title": document.title,
                    "path": str(document.path),
                    "score": result["score"],
                    "matching_chunk": result["matching_chunk"],
                }
            )

        return results


def print_results(results: list[dict]) -> None:
    if not results:
        print("No matching recaps found.")
        return

    for rank, result in enumerate(results, start=1):
        print(f"{rank}. {result['title']}")
        print(f"   File: {result['path']}")
        print(f"   Similarity: {result['score']:.4f}")
        print(f"   Matching chunk: {result['matching_chunk'][:300]}")
        print()


def main():
    parser = argparse.ArgumentParser(
        description="Search basketball recap markdown files semantically."
    )
    parser.add_argument(
        "folder",
        nargs="?",
        default=str(RECAPS_FOLDER),
        help="Folder containing recap markdown files (defaults to the built-in recaps folder).",
    )
    args = parser.parse_args()

    search_engine = SemanticRecapSearch(
        recap_folder=args.folder,
        chunk_size=180,
        chunk_overlap=40,
    )

    print("\nSemantic basketball recap search")
    print("Enter 'q', 'quit', or 'exit' to exit.\n")

    while True:
        query = input("Query: ").strip()

        if query.lower() in {"q", "quit", "exit"}:
            break

        if not query:
            continue

        results = search_engine.search(
            query=query,
            top_k=5,
        )

        print()
        print_results(results)


if __name__ == "__main__":
    main()
